// Automated Resume Download Utility
(function() {
    var RESUME_FILENAME = 'Ghayur_Abbas_AI_Engineer_Resume.pdf';
    var RESUME_BASE64 = '';

    function downloadBlob(blob, filename) {
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        setTimeout(function() {
            if (a.parentNode) a.parentNode.removeChild(a);
            URL.revokeObjectURL(url);
        }, 2000);
    }

    function downloadFromBase64() {
        var binaryString = atob(RESUME_BASE64);
        var len = binaryString.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        var blob = new Blob([bytes], { type: 'application/octet-stream' });
        downloadBlob(blob, RESUME_FILENAME);
    }

    window.downloadResumePdf = async function(e) {
        if (e && e.preventDefault) e.preventDefault();
        try {
            if (window.location && (window.location.protocol === 'http:' || window.location.protocol === 'https:')) {
                var response = await fetch(RESUME_FILENAME);
                if (response.ok) {
                    var rawBlob = await response.blob();
                    var forceDownloadBlob = new Blob([rawBlob], { type: 'application/octet-stream' });
                    downloadBlob(forceDownloadBlob, RESUME_FILENAME);
                    return;
                }
            }
        } catch (err) {
            console.warn('Network fetch not available, using embedded fallback:', err);
        }
        downloadFromBase64();
    };

    function attachHandlers() {
        var downloadButtons = document.querySelectorAll('a[download], #download-resume-btn, .resume-download-btn');
        downloadButtons.forEach(function(btn) {
            btn.onclick = window.downloadResumePdf;
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', attachHandlers);
    } else {
        attachHandlers();
    }
})();
